#!/bin/bash
set -eu
# URL-safe value generated by start_cluster.ps1; psql also quotes it as literal.
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" \
    --set=replication_password="$REPLICATION_PASSWORD" <<'SQL'
CREATE ROLE ecopulse_repl WITH REPLICATION LOGIN PASSWORD :'replication_password';
SELECT pg_create_physical_replication_slot('ecopulse_replica');
SQL
printf '\nhost replication ecopulse_repl 0.0.0.0/0 scram-sha-256\n' >> "$PGDATA/pg_hba.conf"
